// Read-aloud with the browser's built-in speech synthesis (no server, no cost).
// The voice is generated by the device's text-to-speech engine; disclosed on the About page.
const synth = window.speechSynthesis;
let voices = [];
const loadVoices = () => { voices = synth?.getVoices() || []; };
if (synth) { loadVoices(); synth.addEventListener?.('voiceschanged', loadVoices); }

export const speechSupported = () => !!synth;
export function speak(text, lang) {
  if (!synth || !text) return;
  synth.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = lang === 'ja' ? 'ja-JP' : 'en-US';
  const v = voices.find(v => v.lang === u.lang) || voices.find(v => v.lang.startsWith(lang));
  if (v) u.voice = v;
  u.rate = lang === 'ja' ? 1.05 : 1;
  synth.speak(u);
}
export const stopSpeak = () => synth?.cancel();
